CustomField.formula:
IF(
    /* Templates use dedicated template icon */
    IsTemplate__c,

    IMAGE("/resource/Template", "Template", 25, 25),

    /* Active projects can become overdue */
    IF(
        AND(
            DueDate__c < TODAY(),
            NOT(
                OR(
                    ISPICKVAL(Status__c, "Completed"),
                    ISPICKVAL(Status__c, "Cancelled")
                )
            )
        ),

        IMAGE("/resource/Overdue", "Overdue", 25, 25),

        /* Standard status icons */
        IMAGE(
            CASE(
                TEXT(Status__c),

                "Planned", "/resource/Not_Started",
                "In Progress", "/resource/In_Progress",
                "Blocked", "/resource/Blocked",
                "Completed", "/resource/Completed",
                "Cancelled", "/resource/Canceled",

                "/resource/Not_Started"
            ),

            "status icon",
            25,
            25
        )
    )
)
